<template>
  <div class="space-y-4">
    <div
      class="relative flex aspect-square items-center justify-center overflow-hidden rounded-2xl border border-line p-6"
      :class="style.is_transparent ? 'bg-[repeating-conic-gradient(rgb(var(--subtle))_0%_25%,transparent_0%_50%)] bg-[length:18px_18px]' : 'bg-subtle/50'"
      data-testid="qr-preview"
    >
      <!-- SVG is generated by the Lynqr server from validated values only -->
      <div v-if="svg" class="qr-svg h-full w-full transition-opacity duration-150" :class="{ 'opacity-60': loading }" v-html="svg" />
      <div v-else-if="!error" class="skeleton h-3/4 w-3/4" />
      <div v-if="error" class="absolute inset-0 flex flex-col items-center justify-center gap-2 bg-surface/90 p-6 text-center backdrop-blur-sm">
        <AlertCircle class="h-6 w-6 text-amber-500" />
        <p class="text-sm text-fg">{{ error }}</p>
      </div>
      <Loader2 v-if="loading" class="absolute right-3 top-3 h-4 w-4 animate-spin text-fg-subtle" />
    </div>

    <div v-if="result" class="space-y-2">
      <div class="flex flex-wrap items-center gap-2">
        <span v-if="result.check.scannable" class="badge-success" data-testid="scan-ok"><ScanCheck class="h-3 w-3" /> Scans reliably</span>
        <span v-else class="badge-danger" data-testid="scan-fail"><ScanLine class="h-3 w-3" /> May not scan</span>
        <Tip text="Contrast between the code and its background. 4:1 or higher is ideal.">
          <span class="badge-neutral">Contrast {{ result.check.contrast }}:1</span>
        </Tip>
        <span v-if="result.dynamic" class="badge-brand"><Zap class="h-3 w-3" /> Dynamic</span>
        <span v-else class="badge-neutral">Static</span>
      </div>
      <ul v-if="result.check.warnings.length" class="space-y-1.5">
        <li v-for="w in result.check.warnings" :key="w" class="flex gap-2 rounded-lg bg-amber-500/10 px-2.5 py-2 text-xs text-amber-700 dark:text-amber-300">
          <AlertTriangle class="mt-0.5 h-3.5 w-3.5 shrink-0" />{{ w }}
        </li>
      </ul>
      <p class="truncate text-xs text-fg-subtle" :title="result.payload">
        Encodes: <span class="font-mono text-fg-muted">{{ result.dynamic && !qrId ? 'your short scan URL (assigned on save)' : result.payload }}</span>
      </p>
    </div>
  </div>
</template>

<script setup>
import { ref, watch, onBeforeUnmount } from 'vue'
import { AlertCircle, AlertTriangle, Loader2, ScanLine, ScanSearch as ScanCheck, Zap } from 'lucide-vue-next'
import { api } from '../../api/client'
import Tip from '../ui/Tip.vue'

const props = defineProps({
  content: { type: Object, required: true }, // { type, target_url, raw_data, is_dynamic }
  style: { type: Object, required: true },
  qrId: { type: String, default: '' }
})
const emit = defineEmits(['result'])

const svg = ref('')
const result = ref(null)
const error = ref('')
const loading = ref(false)
let timer = null
let controller = null

async function render() {
  controller?.abort()
  controller = new AbortController()
  loading.value = true
  try {
    const res = await api.previewQR({ ...props.content, id: props.qrId, style: props.style, size: 512 }, controller.signal)
    svg.value = res.svg
    result.value = res
    error.value = ''
    emit('result', res)
  } catch (err) {
    if (err.name === 'AbortError') return
    error.value = err.message
    result.value = null
    emit('result', null)
  } finally {
    loading.value = false
  }
}

watch(
  () => [props.content, props.style, props.qrId],
  () => {
    clearTimeout(timer)
    timer = setTimeout(render, 180)
  },
  { deep: true, immediate: true }
)
onBeforeUnmount(() => {
  clearTimeout(timer)
  controller?.abort()
})
</script>

<style scoped>
.qr-svg :deep(svg) {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 4px 12px rgb(0 0 0 / 0.08));
}
</style>
